{"command":"node -e "
const d=require('/tmp/bands.json');
const bands=d.delta.bands;
for(const b of bands){
  if(b.status!=='paired'){ console.log(b.status, 'a.top='+ (b.a&&b.a.top), 'b.top='+(b.b&&b.b.top), 'a.h='+(b.a&&b.a.height),'b.h='+(b.b&&b.b.height)); }
  else {
    const f=[];
    if(Math.abs(b.since_pair.abs)>2) f.push('since='+b.since_pair.abs);
    if(Math.abs(b.height.abs)>2) f.push('h='+b.height.abs);
    if(b.edge.distance>12) f.push('edge='+b.edge.distance);
    if(b.colour.distance>12) f.push('col='+b.colour.distance);
    if(Math.abs(b.gap_above.abs)>2) f.push('gap='+b.gap_above.abs);
    console.log('paired a.top='+b.a.top+' b.top='+b.b.top+(f.length?' FLAG '+f.join(','):' ok'));
  }
}
console.log(JSON.stringify(d.delta.bands_summary));
"","description":"Summarize band pairing flags"}

